	@Test
	public void sameTermOrPreservesExactRdfTermIdentityAcrossFiniteRows() {
		SimpleValueFactory valueFactory = SimpleValueFactory.getInstance();
		Literal integerWithLeadingZero = valueFactory.createLiteral("01", XSD.INTEGER);
		Literal integerWithoutLeadingZero = valueFactory.createLiteral("1", XSD.INTEGER);
		Literal invalidInteger = valueFactory.createLiteral("not-an-integer", XSD.INTEGER);
		Literal leftToRight = valueFactory.createLiteral("hello", "en", Literal.BaseDirection.LTR);
		Literal rightToLeft = valueFactory.createLiteral("hello", "en", Literal.BaseDirection.RTL);
		Value nestedTriple = valueFactory.createTripleTerm(
				valueFactory.createBNode("outer-subject"),
				valueFactory.createIRI("urn:test:predicate"),
				valueFactory.createTripleTerm(valueFactory.createBNode("inner-subject"),
						valueFactory.createIRI("urn:test:inner-predicate"),
						valueFactory.createLiteral("inner-object")));
		List<Value> terms = List.of(integerWithLeadingZero, integerWithoutLeadingZero, invalidInteger,
				valueFactory.createBNode("finite-bnode"), leftToRight, rightToLeft, nestedTriple, invalidInteger,
				nestedTriple);

		TupleExpr tupleExpr = sameTermOrQuery(terms);
		getOptimizer().optimize(tupleExpr, null, EmptyBindingSet.getInstance());

		List<BindingSetAssignment> anchors = findValuesAnchors(tupleExpr);
		assertThat(anchors).singleElement();
		List<Value> expected = List.of(integerWithLeadingZero, integerWithoutLeadingZero, invalidInteger,
				valueFactory.createBNode("finite-bnode"), leftToRight, rightToLeft, nestedTriple);
		List<Value> actual = valuesFor(anchors.get(0));
		assertThat(actual)
				.as("SameTerm uses exact RDF-term identity: lexical numeric variants and base directions stay distinct")
				.containsExactlyElementsOf(expected);
	}

