	@Test
	public void sameTermOrAnchorsConstantValuedVarInEitherOrientation() {
		Value first = SimpleValueFactory.getInstance().createIRI("urn:test:first");
		Value second = SimpleValueFactory.getInstance().createIRI("urn:test:second");

		assertAll(
				() -> assertConstantValuedVarAnchor(false, first, second),
				() -> assertConstantValuedVarAnchor(true, first, second));
	}

	private void assertConstantValuedVarAnchor(boolean reversed, Value first, Value second) {
		Var ordinaryVar = Var.of("o");
		Var constantValuedVar = Var.of("constant", first);
		SameTerm firstTerm = reversed
				? new SameTerm(constantValuedVar.clone(), ordinaryVar.clone())
				: new SameTerm(ordinaryVar.clone(), constantValuedVar.clone());
		SameTerm secondTerm = reversed
				? new SameTerm(new ValueConstant(second), ordinaryVar.clone())
				: new SameTerm(ordinaryVar.clone(), new ValueConstant(second));
		Filter filter = new Filter(new StatementPattern(Var.of("s"), Var.of("p"), Var.of("o")),
				new Or(firstTerm, secondTerm));
		QueryRoot root = new QueryRoot(filter);

		getOptimizer().optimize(root, null, EmptyBindingSet.getInstance());

		assertThat(findValuesAnchors(root))
				.as("constant-valued Vars must be finite SameTerm operands in both orientations: " + reversed)
				.singleElement()
				.satisfies(anchor -> {
					assertThat(anchor.getBindingNames()).containsExactly("o");
					assertThat(valuesFor(anchor)).containsExactly(first, second);
				});
	}

