	@Test
	public void optimizedFiniteAnchorPreservesInitialBindingAndBagMultiplicity() throws Exception {
		Value selected = SimpleValueFactory.getInstance().createIRI("urn:test:selected");
		Value other = SimpleValueFactory.getInstance().createIRI("urn:test:other");
		BindingSet first = new ListBindingSet(List.of("o"), selected);
		BindingSet duplicate = new ListBindingSet(List.of("o"), selected);
		BindingSet second = new ListBindingSet(List.of("o"), other);
		BindingSetAssignment source = new BindingSetAssignment();
		source.setBindingNames(Set.of("o"));
		source.setBindingSets(List.of(first, duplicate, second));
		Filter filter = new Filter(source, new Or(
				new SameTerm(Var.of("o"), new ValueConstant(selected)),
				new SameTerm(new ValueConstant(other), Var.of("o"))));
		TupleExpr original = new QueryRoot(filter);
		TupleExpr optimized = original.clone();
		MapBindingSet initial = new MapBindingSet();
		initial.addBinding("o", selected);

		getOptimizer().optimize(optimized, null, initial);

		assertThat(evaluate(original, initial))
				.as("the control query must retain both duplicate selected rows")
				.hasSize(2);
		assertThat(evaluate(optimized, initial))
				.as("finite anchoring must preserve initial compatibility and bag multiplicity")
				.containsExactlyElementsOf(evaluate(original, initial));
	}

	@Override
	public DisjunctiveConstraintOptimizer getOptimizer() {
		return new DisjunctiveConstraintOptimizer();
	}

	private static Union findUnion(QueryRoot root) {
		if (root.getArg()instanceof Union union) {
			return union;
		}
		if (root.getArg()instanceof Filter filter && filter.getArg()instanceof Union union) {
			return union;
		}
		return null;
	}

	private static boolean containsUnion(TupleExpr tupleExpr) {
		boolean[] found = new boolean[1];
		tupleExpr.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(Union node) {
				found[0] = true;
			}
		});
		return found[0];
	}

	private static List<BindingSetAssignment> findValuesAnchors(TupleExpr tupleExpr) {
		List<BindingSetAssignment> assignments = new ArrayList<>();
		tupleExpr.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			protected void meetNode(QueryModelNode node) {
				if (node instanceof BindingSetAssignment assignment) {
					assignments.add(assignment);
				}
				super.meetNode(node);
			}
		});
		return assignments;
	}

	private static List<Value> valuesFor(BindingSetAssignment assignment) {
		List<Value> values = new ArrayList<>();
		for (BindingSet bindingSet : assignment.getBindingSets()) {
			values.add(bindingSet.getValue("o"));
		}
		return values;
	}

	private static TupleExpr sameTermOrQuery(List<Value> values) {
		if (values.size() < 2) {
			throw new IllegalArgumentException("at least two finite terms are required");
		}
		Or condition = new Or(new SameTerm(Var.of("o"), new ValueConstant(values.get(0))),
				new SameTerm(Var.of("o"), new ValueConstant(values.get(1))));
		for (Value value : values.subList(2, values.size())) {
			condition = new Or(condition, new SameTerm(Var.of("o"), new ValueConstant(value)));
		}
		return new QueryRoot(new Filter(new StatementPattern(Var.of("s"), Var.of("p"), Var.of("o")), condition));
	}

	private static List<BindingSet> evaluate(TupleExpr tupleExpr, BindingSet bindings) throws Exception {
		DefaultEvaluationStrategy strategy = new DefaultEvaluationStrategy(new EmptyTripleSource(), null);
		try (CloseableIteration<BindingSet> iteration = strategy.precompile(tupleExpr).evaluate(bindings)) {
			return Iterations.asList(iteration);
		}
	}

